{-| @Backend.Runtime.Host.File — files, directories and open handles, as `Pudu.Eval.Io` and `Pudu.Eval.Handle` answer them, each refusal worded as the interpreter's runtime words it. -}
module Pudu.Backend.Runtime.Host.File (hostFileParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. -}
hostFileParts :: [(Text, [Text], [Text])]
hostFileParts =
  [ ("host_files", ["host_optional", "host_path", "host_fail_io"],
      [ "#include <dirent.h>"
      , "#include <fcntl.h>"
      , "#include <limits.h>"
      , "#include <sys/stat.h>"
      , "/* A refusal that names no path of its own: the operation's words hold both. */"
      , "PUDU_OPTIONAL static inline void pudu_host_fail_pair(const char *operation, pudu_text from, pudu_text to, int code) {"
      , "  size_t named = strlen(operation);"
      , "  char *words = malloc(named + from.length + to.length + 12);"
      , "  char *cursor = words;"
      , "  pudu_text none = {(const unsigned char *)\"\", 0, NULL};"
      , "  if (words == NULL) pudu_memory_failure();"
      , "  memcpy(cursor, operation, named); cursor += named;"
      , "  *cursor++ = ' '; *cursor++ = '\\'';"
      , "  if (from.length != 0) memcpy(cursor, from.bytes, from.length);"
      , "  cursor += from.length;"
      , "  memcpy(cursor, \"' to '\", 6); cursor += 6;"
      , "  if (to.length != 0) memcpy(cursor, to.bytes, to.length);"
      , "  cursor += to.length;"
      , "  *cursor++ = '\\''; *cursor = 0;"
      , "  pudu_host_fail_io(none, words, code);"
      , "  free(words);"
      , "}"
      , "/* Every byte through the descriptor, or the error number. */"
      , "PUDU_OPTIONAL static inline int pudu_host_write_all(int descriptor, const unsigned char *bytes, size_t length) {"
      , "  while (length != 0) {"
      , "    ssize_t wrote = write(descriptor, bytes, length);"
      , "    if (wrote < 0) { if (errno == EINTR) continue; return errno; }"
      , "    bytes += wrote;"
      , "    length -= (size_t)wrote;"
      , "  }"
      , "  return 0;"
      , "}"
      ])
  , ("host_read_file", ["host_files", "host_done", "host_grow", "text_allocate", "host_text_input"],
      [ "/* The leading byte of the first malformed sequence, or -1. */"
      , "static int pudu_host_invalid_text(const unsigned char *bytes, size_t length) {"
      , "  for (size_t i = 0; i < length;) {"
      , "    unsigned char lead = bytes[i], low, high;"
      , "    size_t width = pudu_host_text_width(lead, &low, &high);"
      , "    if (width == 0 || width > length - i) return lead;"
      , "    if (width > 1 && (bytes[i + 1] < low || bytes[i + 1] > high)) return lead;"
      , "    for (size_t k = 2; k < width; ++k) if (bytes[i + k] < 0x80 || bytes[i + k] > 0xBF) return lead;"
      , "    i += width;"
      , "  }"
      , "  return -1;"
      , "}"
      , "/* The whole file as text. A directory opens and is refused afterwards, and"
      , "   bytes that are not UTF-8 are refused at the first one that is not. */"
      , "static pudu_text pudu_host_read_file(pudu_text path) {"
      , "  pudu_text none = {(const unsigned char *)\"\", 0, NULL}, text;"
      , "  char *name = pudu_host_path(path);"
      , "  int descriptor = open(name, O_RDONLY);"
      , "  struct stat found;"
      , "  unsigned char *bytes = NULL, *owned;"
      , "  size_t held = 0, room = 0;"
      , "  free(name);"
      , "  if (descriptor < 0) { pudu_host_fail_io(path, \"openFile\", errno); return none; }"
      , "  if (fstat(descriptor, &found) == 0 && S_ISDIR(found.st_mode)) {"
      , "    (void)close(descriptor);"
      , "    pudu_host_fail_reason(path, \"openFile\", \"inappropriate type\", \"is a directory\");"
      , "    return none;"
      , "  }"
      , "  for (;;) {"
      , "    ssize_t got;"
      , "    if (held == room) {"
      , "      room = room < 4096 ? 4096 : room * 2;"
      , "      bytes = pudu_host_grow(bytes, room);"
      , "    }"
      , "    got = read(descriptor, bytes + held, room - held);"
      , "    if (got < 0) {"
      , "      int code = errno;"
      , "      if (code == EINTR) continue;"
      , "      (void)close(descriptor);"
      , "      free(bytes);"
      , "      pudu_host_fail_io(path, \"hGetContents\", code);"
      , "      return none;"
      , "    }"
      , "    if (got == 0) break;"
      , "    held += (size_t)got;"
      , "  }"
      , "  (void)close(descriptor);"
      , "  int invalid = pudu_host_invalid_text(bytes, held);"
      , "  if (invalid >= 0) {"
      , "    free(bytes);"
      , "    pudu_host_fail_text_byte(path, \"hGetContents\", invalid);"
      , "    return none;"
      , "  }"
      , "  text = pudu_text_allocate(held, &owned);"
      , "  if (held != 0) memcpy(owned, bytes, held);"
      , "  free(bytes);"
      , "  pudu_host_done(0);"
      , "  return text;"
      , "}"
      ])
  , ("host_write_file", ["host_files", "host_done"],
      [ "/* The text as the file's whole contents (mode 0) or after them (mode 1). */"
      , "static int pudu_host_write_file(pudu_text path, pudu_text contents, int mode) {"
      , "  char *name = pudu_host_path(path);"
      , "  int descriptor = open(name, O_WRONLY | O_CREAT | (mode ? O_APPEND : O_TRUNC), 0666);"
      , "  int code;"
      , "  free(name);"
      , "  if (descriptor < 0) { pudu_host_fail_io(path, \"withFile\", errno); return 0; }"
      , "  code = pudu_host_write_all(descriptor, contents.bytes, contents.length);"
      , "  if (close(descriptor) != 0 && code == 0) code = errno;"
      , "  if (code != 0) { pudu_host_fail_io(path, \"withFile\", code); return 0; }"
      , "  pudu_host_done(0);"
      , "  return 1;"
      , "}"
      ])
  , ("host_file_exists", ["host_files"],
      [ "/* Mode 0: a file or a directory is there. Mode 1: a directory is. */"
      , "static int pudu_host_file_exists(pudu_text path, int mode) {"
      , "  char *name = pudu_host_path(path);"
      , "  struct stat found;"
      , "  int present = stat(name, &found) == 0;"
      , "  free(name);"
      , "  return present && (mode == 0 || S_ISDIR(found.st_mode));"
      , "}"
      ])
  , ("host_path_step", ["host_files", "host_done"],
      [ "/* One system call on one path: 0 unlink, 1 mkdir, 2 rmdir. */"
      , "static int pudu_host_path_step(pudu_text path, int step) {"
      , "  static const char *const words[] = {\"removeLink\", \"createDirectory\", \"removeDirectory\"};"
      , "  char *name = pudu_host_path(path);"
      , "  int failed = step == 0 ? unlink(name) : step == 1 ? mkdir(name, 0777) : rmdir(name);"
      , "  int code = errno;"
      , "  free(name);"
      , "  if (failed != 0) { pudu_host_fail_io(path, words[step], code); return 0; }"
      , "  pudu_host_done(0);"
      , "  return 1;"
      , "}"
      ])
  , ("host_create_directory", ["host_files", "host_done"],
      [ "/* The directory and every parent it needs; one already there is done. A"
      , "   failure leaves the error number and how much of the path it names. */"
      , "static int pudu_host_make(char *name, size_t length, size_t *failed) {"
      , "  struct stat found;"
      , "  size_t parent = length;"
      , "  char kept;"
      , "  int code;"
      , "  if (mkdir(name, 0777) == 0) return 1;"
      , "  code = errno;"
      , "  if (code == EEXIST && stat(name, &found) == 0 && S_ISDIR(found.st_mode)) return 1;"
      , "  while (parent > 0 && name[parent - 1] == '/') parent -= 1;"
      , "  while (parent > 0 && name[parent - 1] != '/') parent -= 1;"
      , "  while (parent > 0 && name[parent - 1] == '/') parent -= 1;"
      , "  if (code != ENOENT || parent == 0) { errno = code; *failed = length; return 0; }"
      , "  kept = name[parent];"
      , "  name[parent] = 0;"
      , "  if (!pudu_host_make(name, parent, failed)) return 0;"
      , "  name[parent] = kept;"
      , "  if (mkdir(name, 0777) == 0) return 1;"
      , "  code = errno;"
      , "  if (code == EEXIST && stat(name, &found) == 0 && S_ISDIR(found.st_mode)) return 1;"
      , "  errno = code;"
      , "  *failed = length;"
      , "  return 0;"
      , "}"
      , "static int pudu_host_create_directory(pudu_text given) {"
      , "  char *name = pudu_host_path(given);"
      , "  pudu_text path = given;"
      , "  size_t failed, kept = 0;"
      , "  /* Repeated separators are one, as the interpreter's runtime reads a path. */"
      , "  for (size_t index = 0; index < given.length; ++index)"
      , "    if (name[index] != '/' || kept == 0 || name[kept - 1] != '/') name[kept++] = name[index];"
      , "  name[kept] = 0;"
      , "  path.bytes = (const unsigned char *)name;"
      , "  path.length = kept;"
      , "  path.owner = NULL;"
      , "  failed = kept;"
      , "  if (!pudu_host_make(name, path.length, &failed)) {"
      , "    int code = errno;"
      , "    pudu_text named = path;"
      , "    named.length = failed;"
      , "    pudu_host_fail_io(named, \"createDirectory\", code);"
      , "    free(name);"
      , "    return 0;"
      , "  }"
      , "  free(name);"
      , "  pudu_host_done(0);"
      , "  return 1;"
      , "}"
      ])
  , ("host_rename_path", ["host_files", "host_done"],
      [ "static int pudu_host_rename_path(pudu_text from, pudu_text to) {"
      , "  char *source = pudu_host_path(from), *target = pudu_host_path(to);"
      , "  int failed = rename(source, target), code = errno;"
      , "  free(source);"
      , "  free(target);"
      , "  if (failed != 0) { pudu_host_fail_pair(\"renamePath:rename\", from, to, code); return 0; }"
      , "  pudu_host_done(0);"
      , "  return 1;"
      , "}"
      ])
  , ("host_file_size", ["host_files", "host_done", "kernel_int"],
      [ "static pudu_int pudu_host_file_size(pudu_text path) {"
      , "  char *name = pudu_host_path(path);"
      , "  struct stat found;"
      , "  int failed = stat(name, &found), code = errno;"
      , "  free(name);"
      , "  if (failed != 0) { pudu_host_fail_io(path, \"getFileSize:getFileStatus\", code); return pudu_kernel_int(0); }"
      , "  pudu_host_done(0);"
      , "  return pudu_kernel_int((int64_t)found.st_size);"
      , "}"
      ])
  , ("host_permissions_of", ["host_files", "host_done", "kernel_int"],
      [ "/* Readable 1, writable 2, executable 4, searchable 8, for this process. */"
      , "static pudu_int pudu_host_permissions_of(pudu_text path) {"
      , "  char *name = pudu_host_path(path);"
      , "  struct stat found;"
      , "  int64_t mask = 0;"
      , "  if (stat(name, &found) != 0) {"
      , "    int code = errno;"
      , "    free(name);"
      , "    pudu_host_fail_io(path, \"getPermissions:getFileStatus\", code);"
      , "    return pudu_kernel_int(0);"
      , "  }"
      , "  if (access(name, R_OK) == 0) mask += 1;"
      , "  if (access(name, W_OK) == 0) mask += 2;"
      , "  if (access(name, X_OK) == 0) mask += S_ISDIR(found.st_mode) ? 8 : 4;"
      , "  free(name);"
      , "  pudu_host_done(0);"
      , "  return pudu_kernel_int(mask);"
      , "}"
      ])
  , ("host_set_permissions_of", ["host_files", "host_done", "kernel_signed"],
      [ "/* The owner's bits from the same mask; the others stay. */"
      , "static int pudu_host_set_permissions_of(pudu_text path, pudu_int mask) {"
      , "  char *name = pudu_host_path(path);"
      , "  int64_t wanted = pudu_kernel_signed(mask.bits);"
      , "  struct stat found;"
      , "  mode_t mode;"
      , "  int code = 0;"
      , "  if (stat(name, &found) != 0) {"
      , "    code = errno;"
      , "    free(name);"
      , "    pudu_host_fail_io(path, \"setPermissions:getFileStatus\", code);"
      , "    return 0;"
      , "  }"
      , "  mode = found.st_mode & (mode_t)~(S_IRUSR | S_IWUSR | S_IXUSR) & 07777;"
      , "  if ((wanted / 1) % 2 == 1) mode |= S_IRUSR;"
      , "  if ((wanted / 2) % 2 == 1) mode |= S_IWUSR;"
      , "  if ((wanted / 4) % 2 == 1 || (wanted / 8) % 2 == 1) mode |= S_IXUSR;"
      , "  if (chmod(name, mode) != 0) code = errno;"
      , "  free(name);"
      , "  if (code != 0) { pudu_host_fail_io(path, \"setPermissions:setFileMode\", code); return 0; }"
      , "  pudu_host_done(0);"
      , "  return 1;"
      , "}"
      ])
  , ("host_is_symbolic_link", ["host_files", "host_done"],
      [ "static int pudu_host_is_symbolic_link(pudu_text path) {"
      , "  char *name = pudu_host_path(path);"
      , "  struct stat found;"
      , "  int failed = lstat(name, &found), code = errno;"
      , "  free(name);"
      , "  if (failed != 0) { pudu_host_fail_io(path, \"pathIsSymbolicLink:getSymbolicLinkStatus\", code); return 0; }"
      , "  pudu_host_done(0);"
      , "  return S_ISLNK(found.st_mode);"
      , "}"
      ])
  , ("host_create_symbolic_link", ["host_files", "host_done"],
      [ "static int pudu_host_create_symbolic_link(pudu_text target, pudu_text link) {"
      , "  char *aimed = pudu_host_path(target), *name = pudu_host_path(link);"
      , "  int failed = symlink(aimed, name), code = errno;"
      , "  free(aimed);"
      , "  free(name);"
      , "  if (failed != 0) { pudu_host_fail_pair(\"createFileLink:createSymbolicLink\", target, link, code); return 0; }"
      , "  pudu_host_done(0);"
      , "  return 1;"
      , "}"
      ])
  , ("host_canonical_path", ["host_files", "host_done", "text_copy", "memory_failure"],
      [ "/* The path with every link and relative step resolved; one that is not"
      , "   there has none to resolve. */"
      , "static pudu_text pudu_host_canonical_path(pudu_text path) {"
      , "  pudu_text none = {(const unsigned char *)\"\", 0, NULL}, text;"
      , "  char *name = pudu_host_path(path);"
      , "  struct stat found;"
      , "  char *resolved;"
      , "  if (stat(name, &found) != 0) { free(name); pudu_host_fail_reason(path, \"canonicalPath\", \"does not exist\", \"\"); return none; }"
      , "  resolved = malloc(PATH_MAX + 1);"
      , "  if (resolved == NULL) pudu_memory_failure();"
      , "  if (realpath(name, resolved) == NULL) { int code = errno; free(name); free(resolved); pudu_host_fail_io(path, \"canonicalizePath\", code); return none; }"
      , "  free(name);"
      , "  text = pudu_text_copy(resolved, strlen(resolved));"
      , "  free(resolved);"
      , "  pudu_host_done(0);"
      , "  return text;"
      , "}"
      ])
  , ("host_list_directory", ["host_files", "host_done", "array", "array_reserve", "text_copy"],
      [ "/* Every name in the directory but its own and its parent's, as the system"
      , "   hands them out. */"
      , "static pudu_box *pudu_host_list_directory(pudu_text path) {"
      , "  char *name = pudu_host_path(path);"
      , "  DIR *stream = opendir(name);"
      , "  int code = errno;"
      , "  pudu_box *array;"
      , "  struct dirent *entry;"
      , "  free(name);"
      , "  if (stream == NULL) { pudu_host_fail_io(path, \"getDirectoryContents:openDirStream\", code); return NULL; }"
      , "  array = pudu_array_new(0);"
      , "  while ((entry = readdir(stream)) != NULL) {"
      , "    const char *found = entry->d_name;"
      , "    if (strcmp(found, \".\") == 0 || strcmp(found, \"..\") == 0) continue;"
      , "    pudu_array_reserve(array, pudu_array_length(array) + 1);"
      , "    array->fields[0].items->cells[pudu_array_length(array)].text = pudu_text_copy(found, strlen(found));"
      , "    pudu_array_length(array) += 1;"
      , "  }"
      , "  (void)closedir(stream);"
      , "  pudu_host_done(0);"
      , "  return array;"
      , "}"
      ])
  , ("host_stage", ["host_optional", "host_files", "host_time"],
      [ "/* A new file in the directory, made so no other process can claim its"
      , "   name: the front, digits of the system's choosing, then `.tmp`. The path"
      , "   is the caller's to free; NULL leaves the error number. */"
      , "PUDU_OPTIONAL static inline char *pudu_host_stage(const char *directory, size_t held, const unsigned char *front, size_t fronted, int *descriptor) {"
      , "  static unsigned long turn = 0;"
      , "  char *name = malloc(held + fronted + 40);"
      , "  if (name == NULL) pudu_memory_failure();"
      , "  for (int attempt = 0; attempt < 1000; ++attempt) {"
      , "    size_t at = 0;"
      , "    unsigned long digits = (unsigned long)getpid() * 1000003UL + (unsigned long)time(NULL) * 7919UL + turn++;"
      , "    if (held != 0) { memcpy(name, directory, held); at = held; if (name[at - 1] != '/') name[at++] = '/'; }"
      , "    if (fronted != 0) memcpy(name + at, front, fronted);"
      , "    at += fronted;"
      , "    snprintf(name + at, 36, \"%lu-%d.tmp\", digits % 1000000007UL, attempt);"
      , "    *descriptor = open(name, O_RDWR | O_CREAT | O_EXCL, 0600);"
      , "    if (*descriptor >= 0) return name;"
      , "    if (errno != EEXIST) break;"
      , "  }"
      , "  free(name);"
      , "  return NULL;"
      , "}"
      ])
  , ("host_create_temporary_file", ["host_stage", "host_done", "host_time", "text_copy"],
      [ "static pudu_text pudu_host_create_temporary_file(pudu_text directory, pudu_text prefix) {"
      , "  pudu_text none = {(const unsigned char *)\"\", 0, NULL}, text;"
      , "  char *held = pudu_host_path(directory);"
      , "  int descriptor;"
      , "  char *name = pudu_host_stage(held, directory.length, prefix.bytes, prefix.length, &descriptor);"
      , "  int code = errno;"
      , "  free(held);"
      , "  if (name == NULL) { pudu_host_fail_io(directory, \"openBinaryTempFile\", code); return none; }"
      , "  (void)close(descriptor);"
      , "  text = pudu_text_copy(name, strlen(name));"
      , "  free(name);"
      , "  pudu_host_done(0);"
      , "  return text;"
      , "}"
      ])
  , ("host_write_atomically", ["host_stage", "host_done", "host_time"],
      [ "/* A private stage beside the destination, filled, given the destination's"
      , "   mode or a new file's, then renamed over it. */"
      , "static int pudu_host_write_atomically(pudu_text destination, pudu_box *contents) {"
      , "  pudu_text bytes = contents->fields[0].text, directory = destination, none = {(const unsigned char *)\"\", 0, NULL};"
      , "  char *target = pudu_host_path(destination), *stage, *front;"
      , "  size_t split = destination.length, named;"
      , "  struct stat found;"
      , "  mode_t mode;"
      , "  int descriptor, code;"
      , "  while (split > 0 && destination.bytes[split - 1] != '/') split -= 1;"
      , "  named = destination.length - split;"
      , "  directory.length = split > 1 ? split - 1 : split;"
      , "  front = malloc(named + 2);"
      , "  if (front == NULL) pudu_memory_failure();"
      , "  front[0] = '.';"
      , "  if (named != 0) memcpy(front + 1, destination.bytes + split, named);"
      , "  stage = pudu_host_stage((const char *)destination.bytes, directory.length, (const unsigned char *)front, named + 1, &descriptor);"
      , "  code = errno;"
      , "  free(front);"
      , "  if (stage == NULL) {"
      , "    free(target);"
      , "    if (directory.length == 0) directory = (pudu_text){(const unsigned char *)\".\", 1, NULL};"
      , "    pudu_host_fail_io(directory, \"openBinaryTempFile\", code);"
      , "    return 0;"
      , "  }"
      , "  code = pudu_host_write_all(descriptor, bytes.bytes, bytes.length);"
      , "  if (code == 0) {"
      , "    if (stat(target, &found) == 0) mode = found.st_mode & 07777;"
      , "    else { mode_t mask = umask(0); (void)umask(mask); mode = 0666 & (mode_t)~mask; }"
      , "    if (fchmod(descriptor, mode) != 0) code = errno;"
      , "  }"
      , "  if (close(descriptor) != 0 && code == 0) code = errno;"
      , "  if (code == 0 && rename(stage, target) != 0) {"
      , "    code = errno;"
      , "    (void)unlink(stage);"
      , "    free(stage);"
      , "    free(target);"
      , "    pudu_host_fail_pair(\"renamePath:rename\", none, destination, code);"
      , "    return 0;"
      , "  }"
      , "  if (code != 0) { (void)unlink(stage); free(stage); free(target); pudu_host_fail_io(destination, \"hPut\", code); return 0; }"
      , "  free(stage);"
      , "  free(target);"
      , "  pudu_host_done(0);"
      , "  return 1;"
      , "}"
      ])
  ]
